-- Geriatrics: PK/PD Shifts
-- US MD/MBBS (4th Year) clinical case blocks
-- Target platform: Supabase (Postgres)
-- Topic Slug: geri-pharmacokinetic-shifts

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
