BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'geri-pharmacokinetic-shifts' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic slug % not found.', 'geri-pharmacokinetic-shifts';
    END IF;

    ---------------------------------------------------------------------------
    -- CASE 01: Benzodiazepine Accumulation and Body Fat (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Benzodiazepine Accumulation and Body Fat (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Benzodiazepine Accumulation and Body Fat (V1)', 'A 69-year-old female is brought to the clinic by her child due to progressive daytime drowsiness and lethargy over the past 2 weeks. The child notes the patient was started on diazepam for anxiety 14 days ago. Physical exam shows a healthy older adult with a body weight of 170 lbs. There are no focal motor deficits, but the patient has significant psychomotor slowing and unsteady gait.', 1) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 69-year-old female is brought to the clinic by her child due to progressive daytime drowsiness and lethargy over the past 2 weeks. The child notes the patient was started on diazepam for anxiety 14 days ago. Physical exam shows a healthy older adult with a body weight of 170 lbs. There are no focal motor deficits, but the patient has significant psychomotor slowing and unsteady gait.', "order" = 1 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the primary age-related physiological mechanism explaining this clinical presentation?', '["A rapid acceleration of hepatic Phase I CYP450 metabolism leading to toxic levels of active metabolites", "An increase in serum albumin levels resulting in a larger bound inactive fraction of diazepam", "A decrease in total body fat percentage causing higher peak serum drug levels", "An increased total body fat percentage expanding the volume of distribution for lipophilic drugs like diazepam, combined with decreased hepatic Phase I clearance, resulting in a prolonged elimination half-life and drug accumulation", "A selective upregulation of GABA-A receptors in the elderly leading to increased receptor affinity for benzodiazepines"]'::jsonb, 3, 'Aging is associated with a decrease in total body water/lean mass and an increase in total body fat percentage. Highly lipophilic drugs (like diazepam) distribute widely into adipose tissue, expanding their volume of distribution (Vd). This, combined with age-related GFR/hepatic clearance decline, prolongs their half-life, causing drug accumulation.'),
    (v_case_id, 'Which of the following benzodiazepines is preferred in older adults because it bypasses Phase I CYP450 oxidation and undergoes direct Phase II conjugation, avoiding toxic accumulation?', '["Flurazepam", "Diazepam", "Lorazepam", "Clonazepam", "Chlordiazepoxide"]'::jsonb, 2, 'The preferred benzodiazepines in the elderly are Lorazepam, Oxazepam, and Temazepam (the ''LOT'' drugs) because they bypass Phase I hepatic oxidation (which declines with age) and undergo direct Phase II conjugation (glucuronidation), which remains preserved.'),
    (v_case_id, 'Which of the following clinical tools is most appropriate for a pharmacist or physician to consult when evaluating a multi-drug regimen for potentially inappropriate medications in an elderly patient?', '["AGS Beers Criteria", "HAS-BLED Score", "Braden Scale Tool", "Gage Score", "Mini Nutritional Assessment"]'::jsonb, 0, 'The AGS Beers Criteria is the gold-standard reference list of medications that should be avoided or used with caution in older adults due to high risk of adverse drug reactions, including falls and cognitive decline.');

