    ---------------------------------------------------------------------------
    -- CASE 06: Phenytoin Toxicity and Serum Albumin (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Phenytoin Toxicity and Serum Albumin (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Phenytoin Toxicity and Serum Albumin (V1)', 'A 89-year-old female with a history of focal epilepsy and severe osteoarthritis is admitted to the hospital due to acute onset of ataxia, slurred speech, and nystagmus. The patient has been taking phenytoin for epilepsy and has a history of chronic malnutrition. Labs show a total serum phenytoin level of 14 µg/mL (normal 10-20 µg/mL), but serum albumin is significantly reduced at 2.2 g/dL.', 6) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 89-year-old female with a history of focal epilepsy and severe osteoarthritis is admitted to the hospital due to acute onset of ataxia, slurred speech, and nystagmus. The patient has been taking phenytoin for epilepsy and has a history of chronic malnutrition. Labs show a total serum phenytoin level of 14 µg/mL (normal 10-20 µg/mL), but serum albumin is significantly reduced at 2.2 g/dL.', "order" = 6 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the best explanation for this patient''s phenytoin toxicity despite a normal total serum phenytoin level?', '["Hypoalbuminemia increases the renal clearance of phenytoin, leading to subtherapeutic anticonvulsant activity", "The patient has developed an acute allergic cerebellar reaction to phenytoin that is independent of serum levels; discontinue the drug immediately", "A normal total level rule out phenytoin toxicity; the patient''s symptoms are caused by an acute ischemic stroke in the posterior fossa", "Decreased serum albumin levels lead to a reduced protein-bound fraction and a significantly increased free (active) fraction of phenytoin, which drives toxicity; measure the free phenytoin level and adjust the dose", "Malnutrition has caused an upregulation of phenytoin receptors in the central nervous system"]'::jsonb, 3, 'Phenytoin is highly protein-bound (primarily to albumin). In patients with hypoalbuminemia (due to malnutrition or liver disease), the bound fraction decreases, leading to a higher ''free'' (biologically active) fraction. Since standard assays measure total phenytoin, a normal level can mask a toxic free level. Dosing should be guided by free phenytoin levels or corrected using the Winter-Tozer equation.'),
    (v_case_id, 'What is the standard formula used to estimate the corrected phenytoin concentration in a patient with hypoalbuminemia?', '["Winter-Tozer Equation", "Cockcroft-Gault Equation", "Friedewald Equation", "CKD-EPI Equation", "Henderson-Hasselbalch Equation"]'::jsonb, 0, 'The Winter-Tozer equation is: Corrected Phenytoin = Total Phenytoin / ((0.2 * Albumin) + 0.1). It is used to estimate the active phenytoin level in patients with serum albumin < 3.2 g/dL.'),
    (v_case_id, 'Which of the following represents a classic clinical sign of toxic phenytoin exposure that is easily assessed at the bedside?', '["Horizontal gaze nystagmus and cerebellar ataxia", "Palpable purpura on the lower extremities", "Bilateral pupillary constriction (miosis) and bradycardia", "Generalized flaccid paralysis and hyperpyrexia", "Acute urinary retention and abdominal distension"]'::jsonb, 0, 'Phenytoin toxicity primarily manifests as cerebellar and vestibular symptoms: horizontal gaze nystagmus, slurred speech, dysmetria, and ataxia. In severe cases, it can progress to lethargy, coma, or seizures.');

