    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the best explanation for this patient''s phenytoin toxicity despite a normal total serum phenytoin level?', '["Malnutrition has caused an upregulation of phenytoin receptors in the central nervous system", "The patient has developed an acute allergic cerebellar reaction to phenytoin that is independent of serum levels; discontinue the drug immediately", "A normal total level rule out phenytoin toxicity; the patient''s symptoms are caused by an acute ischemic stroke in the posterior fossa", "Hypoalbuminemia increases the renal clearance of phenytoin, leading to subtherapeutic anticonvulsant activity", "Decreased serum albumin levels lead to a reduced protein-bound fraction and a significantly increased free (active) fraction of phenytoin, which drives toxicity; measure the free phenytoin level and adjust the dose"]'::jsonb, 4, 'Phenytoin is highly protein-bound (primarily to albumin). In patients with hypoalbuminemia (due to malnutrition or liver disease), the bound fraction decreases, leading to a higher ''free'' (biologically active) fraction. Since standard assays measure total phenytoin, a normal level can mask a toxic free level. Dosing should be guided by free phenytoin levels or corrected using the Winter-Tozer equation.'),
    (v_case_id, 'What is the standard formula used to estimate the corrected phenytoin concentration in a patient with hypoalbuminemia?', '["Henderson-Hasselbalch Equation", "Friedewald Equation", "Cockcroft-Gault Equation", "Winter-Tozer Equation", "CKD-EPI Equation"]'::jsonb, 3, 'The Winter-Tozer equation is: Corrected Phenytoin = Total Phenytoin / ((0.2 * Albumin) + 0.1). It is used to estimate the active phenytoin level in patients with serum albumin < 3.2 g/dL.'),
