    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the best explanation for this patient''s phenytoin toxicity despite a normal total serum phenytoin level?', '["Decreased serum albumin levels lead to a reduced protein-bound fraction and a significantly increased free (active) fraction of phenytoin, which drives toxicity; measure the free phenytoin level and adjust the dose", "A normal total level rule out phenytoin toxicity; the patient''s symptoms are caused by an acute ischemic stroke in the posterior fossa", "The patient has developed an acute allergic cerebellar reaction to phenytoin that is independent of serum levels; discontinue the drug immediately", "Malnutrition has caused an upregulation of phenytoin receptors in the central nervous system", "Hypoalbuminemia increases the renal clearance of phenytoin, leading to subtherapeutic anticonvulsant activity"]'::jsonb, 0, 'Phenytoin is highly protein-bound (primarily to albumin). In patients with hypoalbuminemia (due to malnutrition or liver disease), the bound fraction decreases, leading to a higher ''free'' (biologically active) fraction. Since standard assays measure total phenytoin, a normal level can mask a toxic free level. Dosing should be guided by free phenytoin levels or corrected using the Winter-Tozer equation.'),
    (v_case_id, 'What is the standard formula used to estimate the corrected phenytoin concentration in a patient with hypoalbuminemia?', '["CKD-EPI Equation", "Henderson-Hasselbalch Equation", "Cockcroft-Gault Equation", "Winter-Tozer Equation", "Friedewald Equation"]'::jsonb, 3, 'The Winter-Tozer equation is: Corrected Phenytoin = Total Phenytoin / ((0.2 * Albumin) + 0.1). It is used to estimate the active phenytoin level in patients with serum albumin < 3.2 g/dL.'),
    (v_case_id, 'Which of the following represents a classic clinical sign of toxic phenytoin exposure that is easily assessed at the bedside?', '["Palpable purpura on the lower extremities", "Acute urinary retention and abdominal distension", "Bilateral pupillary constriction (miosis) and bradycardia", "Horizontal gaze nystagmus and cerebellar ataxia", "Generalized flaccid paralysis and hyperpyrexia"]'::jsonb, 3, 'Phenytoin toxicity primarily manifests as cerebellar and vestibular symptoms: horizontal gaze nystagmus, slurred speech, dysmetria, and ataxia. In severe cases, it can progress to lethargy, coma, or seizures.');

    ---------------------------------------------------------------------------
    -- CASE 11: Gentamicin Toxicity and the Decreased GFR (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Gentamicin Toxicity and the Decreased GFR (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Gentamicin Toxicity and the Decreased GFR (V1)', 'A 81-year-old female with a severe urinary tract infection is started on intravenous gentamicin therapy. The patient''s baseline serum creatinine is 0.9 mg/dL. On post-treatment day 4, the patient develops severe tinnitus, vertigo, and a sudden drop in urine output. Serum creatinine has risen to 2.3 mg/dL.', 11) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 81-year-old female with a severe urinary tract infection is started on intravenous gentamicin therapy. The patient''s baseline serum creatinine is 0.9 mg/dL. On post-treatment day 4, the patient develops severe tinnitus, vertigo, and a sudden drop in urine output. Serum creatinine has risen to 2.3 mg/dL.', "order" = 11 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the primary cause of this patient''s clinical deterioration, and how could it have been prevented?', '["Allergic interstitial nephritis; immediate administration of high-dose systemic corticosteroids while continuing gentamicin", "A normal age-related reaction to intravenous antibiotics; continue gentamicin and prescribe daily oral meclizine for vertigo", "Bilateral acoustic neuroma formation triggered by the systemic inflammatory response", "Acute bacterial pyelonephritis progression; gentamicin is ineffective and should have been replaced with high-dose ciprofloxacin", "Aminoglycoside-induced nephrotoxicity and ototoxicity; older adults have a physiological decline in GFR despite a ''normal'' baseline creatinine due to sarcopenia, requiring GFR calculation and dosage adjustments"]'::jsonb, 4, 'Aminoglycosides (gentamicin) are highly nephrotoxic and ototoxic, and are cleared exclusively by the kidney. Because baseline muscle mass is lower in the elderly (sarcopenia), serum creatinine can appear normal even with significant GFR decline. Failing to calculate GFR and adjust dosage leads to toxic accumulation.'),
    (v_case_id, 'What is the primary site of cellular damage in aminoglycoside-induced nephrotoxicity?', '["Proximal convoluted tubule cells", "Glomerular basement membrane", "Renal pelvis vascular endothelial cells", "Collecting duct aquaporin channels", "Distal convoluted tubule cells"]'::jsonb, 0, 'Aminoglycosides are filtered by the glomerulus and actively reabsorbed by the proximal convoluted tubule (PCT) cells, where they accumulate in lysosomes and cause necrosis (acute tubular necrosis/ATN).'),
    (v_case_id, 'Which of the following is the most sensitive method of monitoring for early vestibular ototoxicity in a patient receiving an extended course of aminoglycoside therapy?', '["Checking serum calcium levels daily", "Serial audiometry and vestibular function testing", "Continuous electrocardiogram (EKG) monitoring", "Ophthalmic evaluation for visual acuity changes", "Bedside finger-to-nose testing weekly"]'::jsonb, 1, 'Vestibular and cochlear ototoxicity are often irreversible. Serial audiometry and vestibular function testing are the most sensitive methods to detect early, subclinical damage to the hair cells before permanent hearing loss or severe ataxia develops.');

