    ---------------------------------------------------------------------------
    -- CASE 16: Morphine and Decreased First-Pass Metabolism (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Morphine and Decreased First-Pass Metabolism (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Morphine and Decreased First-Pass Metabolism (V1)', 'A 87-year-old female with severe chronic osteoarthritic hip pain is prescribed oral morphine sulfate. The patient has no history of renal or hepatic disease, and is started on a standard ''young adult'' dose. 3 days later, the family brings the patient to the emergency department due to extreme somnolence, pinpoint pupils, and shallow breathing (respiratory rate 8/min).', 16) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 87-year-old female with severe chronic osteoarthritic hip pain is prescribed oral morphine sulfate. The patient has no history of renal or hepatic disease, and is started on a standard ''young adult'' dose. 3 days later, the family brings the patient to the emergency department due to extreme somnolence, pinpoint pupils, and shallow breathing (respiratory rate 8/min).', "order" = 16 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the most likely pharmacological explanation for this patient''s respiratory depression?', '["A complete lack of renal excretion of morphine due to severe age-related structural glomuerular necrosis", "Increased pulmonary clearance of morphine leading to toxic alveolar concentrations", "An immediate, severe allergic hypersensitivity reaction to morphine; administer intravenous epinephrine", "Age-related decrease in hepatic blood flow and liver mass, reducing the first-pass metabolism of morphine and leading to significantly higher systemic bioavailability and blood levels", "A progressive upregulation of mu-opioid receptors in the respiratory center of the brainstem"]'::jsonb, 3, 'Aging is associated with a 30-40% reduction in hepatic blood flow and liver mass. For drugs with a high hepatic extraction ratio that undergo significant first-pass metabolism (like morphine, propranolol, or nitrates), this reduction leads to increased systemic bioavailability, higher serum levels, and a much higher risk of toxicity.'),
    (v_case_id, 'Which of the following represents the immediate antidote of choice for this patient''s opioid-induced respiratory depression?', '["Intravenous flumazenil", "Intravenous acetylcysteine", "Intramuscular epinephrine", "Oral activated charcoal", "Intravenous naloxone"]'::jsonb, 4, 'Naloxone is a competitive mu-opioid receptor antagonist that rapidly reverses all opioid effects, including respiratory depression and sedation. It must be administered in small, titrated doses to avoid triggering acute withdrawal and severe pain.'),
    (v_case_id, 'Which of the following oral opioids has no active metabolites and undergoes direct Phase II glucuronidation, making it generally safer in older adults with mild renal impairment?', '["Meperidine", "Hydromorphone", "Morphine", "Propoxyphene", "Codeine"]'::jsonb, 1, 'Hydromorphone undergoes direct Phase II glucuronidation and has no major active neurotoxic metabolites, making it generally preferred over morphine (whose active metabolite morphine-6-glucuronide accumulates in renal impairment) or meperidine.');

