    ---------------------------------------------------------------------------
    -- CASE 21: Benzodiazepine Sensitivity at the GABA Receptor (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Benzodiazepine Sensitivity at the GABA Receptor (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Benzodiazepine Sensitivity at the GABA Receptor (V1)', 'A 76-year-old female with a history of mild anxiety is started on a low-dose benzodiazepine (lorazepam 0.5 mg). Despite the low dose and normal liver/kidney function tests, the patient becomes highly disoriented, has slurred speech, and falls while attempting to walk to the bathroom. The family is confused because the dose was ''so low.''', 21) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 76-year-old female with a history of mild anxiety is started on a low-dose benzodiazepine (lorazepam 0.5 mg). Despite the low dose and normal liver/kidney function tests, the patient becomes highly disoriented, has slurred speech, and falls while attempting to walk to the bathroom. The family is confused because the dose was ''so low.''', "order" = 21 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What pharmacological principle best explains this exaggerated response in a healthy older adult?', '["Age-related pharmacodynamic changes: increased CNS sensitivity to psychotropic drugs due to alterations in blood-brain barrier permeability and GABA-A receptor response, causing an exaggerated clinical effect at lower doses", "Complete destruction of the cerebral cortex by the low-dose benzodiazepine", "Rapid, toxic accumulation of lorazepam in the gallbladder causing secondary encephalopathy", "Severe allergic vascular reaction leading to transient cerebellar ischemia", "An accelerated rate of renal excretion causing a paradoxical central stimulation"]'::jsonb, 0, 'Older adults exhibit significant pharmacodynamic shifts, including an **increased sensitivity of the central nervous system** to benzodiazepines, sedative-hypnotics, and anticholinergics. This is driven by changes in receptor sensitivity and a more permeable blood-brain barrier, leading to exaggerated sedation and ataxia even with ''normal'' or ''low'' therapeutic serum drug concentrations.'),
    (v_case_id, 'Which of the following represents a classic pharmacodynamic age-related change in older adults?', '["Upregulation of cardiac beta-1 receptors causing chronic tachycardia", "Increased sensitivity to both benzodiazepines and beta-agonists", "Increased sensitivity to sedative-hypnotics (benzodiazepines) and decreased sensitivity to beta-adrenergic agonists/antagonists", "Decreased sensitivity to all psychotropic drugs and increased sensitivity to beta-blockers", "Complete insensitivity to all anticholinergic side effects"]'::jsonb, 2, 'Geriatric pharmacodynamics is characterized by: (1) increased sensitivity to CNS-depressants, sedative-hypnotics, and anticholinergics, and (2) decreased sensitivity to beta-adrenergic stimulation (desensitization of beta-receptors, making both beta-agonists like albuterol and beta-blockers like metoprolol less effective).'),
    (v_case_id, 'Which of the following is the specific benzodiazepine receptor antagonist that can be used to reverse benzodiazepine-induced sedation, though it carries a high risk of triggering seizures in chronic users?', '["Physostigmine", "Pralidoxime", "Atropine", "Naloxone", "Flumazenil"]'::jsonb, 4, 'Flumazenil is a competitive antagonist at the benzodiazepine binding site on the GABA-A receptor. It is used to reverse benzodiazepine overdose but is contraindicated in patients with chronic benzodiazepine dependence due to the high risk of triggering severe, refractory withdrawal seizures.');

