    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the primary cause of this patient''s digoxin toxicity, and how is it clinically managed?', '["A cute ischemic stroke in the occipital lobe; activate the stroke team for tPA", "Primary digitalis allergy; immediately administer high-dose intravenous Vitamin K and schedule an emergent pacemaker", "Digoxin destruction by the liver due to Phase II hepatic conjugation hyperactivation; double the digoxin dose", "A normal age-related reaction to heart failure medications; continue digoxin and prescribe ondansetron for nausea", "Digoxin accumulation due to a physiological decline in GFR (as digoxin is cleared renally) combined with its narrow therapeutic index; discontinue digoxin, correct any electrolyte abnormalities, and administer digoxin-specific antibody fragments (Digibind) for severe toxicity"]'::jsonb, 4, 'Digoxin is a narrow therapeutic index drug cleared renally. Normal aging reduces GFR, leading to digoxin accumulation. Symptoms of toxicity include gastrointestinal distress (nausea/anorexia), cognitive changes, and visual disturbances (xanthopsia/yellow halos). Treatment involves stopping the drug and administering Digibind in severe cases.'),
    (v_case_id, 'Which of the following electrolyte abnormalities significantly increases the risk of digoxin toxicity by promoting digoxin binding to the Na+/K+ ATPase pump?', '["Hypokalemia", "Hyperkalemia", "Hypernatremia", "Hypocalcemia", "Hypermagnesemia"]'::jsonb, 0, 'Digoxin binds competitively to the potassium binding site of the Na+/K+ ATPase pump. Hypokalemia (commonly caused by concurrent loop diuretic use) reduces this competition, allowing more digoxin to bind, which dramatically increases the risk of toxicity even with ''borderline'' therapeutic serum levels.'),
    (v_case_id, 'What is the classic electrocardiogram (EKG) finding associated with therapeutic digoxin use (digitalis effect), which should not be confused with active digoxin toxicity?', '["Severe prolongation of the QTc interval > 500 ms", "Bizarre, alternating bundle branch block (electrical alternans)", "Complete absence of P waves with a regular ventricular response of 120 bpm", "Downsloping ST-segment depression with a ''scooped'' appearance (sagging ST segment)", "Sudden-onset polymorphic ventricular tachycardia (torsades de pointes)"]'::jsonb, 3, 'The ''digitalis effect'' is characterized by a distinctive sagging or scooped ST-segment depression (resembling a Salvador Dali mustache) in lateral leads. It indicates therapeutic digitalis presence, not active toxicity. Toxicity causes arrhythmias (e.g., PVCs, bi-directional VT, heart block).');

