    ---------------------------------------------------------------------------
    -- CASE 31: NSAID Accumulation and Renal Impairment (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'NSAID Accumulation and Renal Impairment (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'NSAID Accumulation and Renal Impairment (V1)', 'A 81-year-old female presents with a 1-week history of severe epigastric pain, dark stools, and oliguria. The patient has been taking high-dose naproxen for chronic back pain for the past 2 weeks. Physical exam shows abdominal tenderness and bilateral pedal edema. Labs show Creatinine of 2.5 mg/dL (baseline 1.0) and severe anemia.', 31) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 81-year-old female presents with a 1-week history of severe epigastric pain, dark stools, and oliguria. The patient has been taking high-dose naproxen for chronic back pain for the past 2 weeks. Physical exam shows abdominal tenderness and bilateral pedal edema. Labs show Creatinine of 2.5 mg/dL (baseline 1.0) and severe anemia.', "order" = 31 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the primary pharmacological basis for this patient''s acute presentation?', '["NSAID-induced acute kidney injury (AKI) and gastric mucosal erosion; older adults have prolonged drug half-lives due to reduced clearance, increasing their susceptibility to prostaglandin-mediated side effects", "A primary allergic reaction to naproxen causing acute liver failure and secondary uremia", "Normal age-related gastric mucosal hypersecretion; continue naproxen and add daily high-dose ranitidine", "Renal artery embolism; perform an immediate surgical embolectomy and double the naproxen dose", "Complete genetic deletion of the cyclooxygenase-2 (COX-2) enzyme in the gastrointestinal tract"]'::jsonb, 0, 'Older adults have a physiological decline in GFR, which prolongs the elimination half-life of NSAIDs. Chronic NSAID accumulation blocks renal prostaglandins (causing afferent vasoconstriction, AKI, and fluid retention) and gastric prostaglandins (impairing mucosal protection, causing bleeding ulcers).'),
    (v_case_id, 'Which of the following represents the primary mechanism of NSAID-induced gastric mucosal injury in older adults?', '["Direct chemical necrosis of the gastric parietal cells due to the highly basic pH of NSAIDs", "Direct mucosal invasion by Helicobacter pylori stimulated by the NSAID molecule", "Inhibition of salivary amylase, leading to incomplete carbohydrate digestion in the stomach", "Inhibition of COX-1, decreasing the synthesis of protective prostaglandins (PGE2, PGI2) that stimulate bicarbonate and mucus secretion and maintain mucosal blood flow", "Upregulation of gastrin receptors causing massive hydrochloric acid hypersecretion"]'::jsonb, 3, 'NSAIDs block COX-1, the constitutive enzyme that synthesizes prostaglandins in the stomach. These prostaglandins are essential for mucosal defense: they stimulate mucus and bicarbonate secretion, maintain mucosal blood flow, and limit acid production. Loss of these prostaglandins leads to mucosal erosion and bleeding.'),
    (v_case_id, 'Which of the following gastroprotective strategies is recommended if chronic NSAID use is absolutely unavoidable in an older adult with high GI risk?', '["Co-prescribe high-dose daily oral calcium carbonate and ensure absolute bed rest", "Co-prescribe daily oral diphenhydramine and restrict all dietary fat", "There are no effective strategies; NSAIDs are strictly contraindicated and cannot be used under any circumstances", "Ensure the patient takes the NSAID with a double shot of vinegar to promote stomach acidity", "Co-prescribe a proton pump inhibitor (e.g., omeprazole) or use a selective COX-2 inhibitor (e.g., celecoxib) at the lowest effective dose"]'::jsonb, 4, 'For high-risk patients who must take an NSAID, co-prescribing a PPI (omeprazole) or using a selective COX-2 inhibitor (celecoxib, which spares gastric COX-1) reduces GI toxicity. However, COX-2 inhibitors still carry significant renal and cardiovascular risks.');

