    ---------------------------------------------------------------------------
    -- CASE 36: Achlorhydria and Iron Malabsorption (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Achlorhydria and Iron Malabsorption (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Achlorhydria and Iron Malabsorption (V1)', 'A 95-year-old female with a history of chronic PPI use (omeprazole 40 mg daily for 5 years) presents with progressive fatigue and shortness of breath. The patient has a balanced diet and no history of bleeding. Labs show a microcytic anemia, low serum iron, and a very low ferritin level of 12 ng/mL.', 36) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 95-year-old female with a history of chronic PPI use (omeprazole 40 mg daily for 5 years) presents with progressive fatigue and shortness of breath. The patient has a balanced diet and no history of bleeding. Labs show a microcytic anemia, low serum iron, and a very low ferritin level of 12 ng/mL.', "order" = 36 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the primary cause of this patient''s iron deficiency anemia, and how is it managed?', '["Normal age-related atrophy of the bone marrow erythroblasts; proceed with immediate blood transfusions", "Severe occult gastrointestinal bleeding driven exclusively by a mechanical PPI toxicity in the duodenum", "PPI-induced achlorhydria (lack of gastric acid) preventing the dissociation and reduction of dietary non-heme iron into its absorbable form; taper and discontinue omeprazole, and supplement with oral iron along with ascorbic acid (Vitamin C)", "Genetic mutation of the transferrin receptor causing complete iron excretion in the urine", "Primary malabsorption of all dietary proteins and fats due to a pancreatic atrophy"]'::jsonb, 2, 'Non-heme iron in food is ferric (Fe3+). It requires an acidic gastric environment to be dissolved and reduced to ferrous (Fe2+), which is the form absorbed in the duodenum. PPIs raise gastric pH, preventing this process and causing iron deficiency. Co-administering Vitamin C (an acidifier) helps restore absorption.'),
    (v_case_id, 'Which of the following forms of calcium supplements is preferred in older adults with achlorhydria (or those on PPIs) because it does not require an acidic gastric pH for dissolution and absorption?', '["Calcium citrate", "Calcium gluconate", "Calcium phosphate", "Oyster shell calcium", "Calcium carbonate"]'::jsonb, 0, 'Calcium carbonate requires a highly acidic environment to dissolve and release ionized calcium. In patients with achlorhydria or on PPIs, its absorption is severely impaired. Calcium citrate does not require acid and is absorbed normally in these patients.'),
    (v_case_id, 'Which of the following diagnostic tests is the most sensitive and specific to differentiate iron deficiency anemia from anemia of chronic disease in an older adult?', '["Peripheral blood smear showing target cells", "Serum ferritin level (ferritin < 30 ng/mL confirms iron deficiency)", "Total serum iron level alone", "Bone marrow biopsy showing ring sideroblasts", "Mean corpuscular volume (MCV) alone"]'::jsonb, 1, 'Ferritin is the primary intracellular iron storage protein. A low serum ferritin (< 30 ng/mL) is highly specific for iron deficiency anemia. Anemia of chronic disease presents with normal or elevated ferritin because it is an acute-phase reactant, reflecting locked-away iron stores.');

