    ---------------------------------------------------------------------------
    -- CASE 41: Warfarin and Sulfonamide Interaction (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Warfarin and Sulfonamide Interaction (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Warfarin and Sulfonamide Interaction (V1)', 'A 89-year-old female taking warfarin for atrial fibrillation is diagnosed with a urinary tract infection and is prescribed trimethoprim-sulfamethoxazole (TMP-SMX). 4 days later, the patient is admitted with a massive epistaxis and severe hematuria. Labs show an INR of 8.5 (therapeutic range 2.0-3.0).', 41) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 89-year-old female taking warfarin for atrial fibrillation is diagnosed with a urinary tract infection and is prescribed trimethoprim-sulfamethoxazole (TMP-SMX). 4 days later, the patient is admitted with a massive epistaxis and severe hematuria. Labs show an INR of 8.5 (therapeutic range 2.0-3.0).', "order" = 41 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the primary pharmacological mechanism behind this dangerous drug interaction?', '["TMP-SMX directly stimulates the synthesis of clotting factors in the liver, causing a paradoxical rebound anticoagulation", "TMP-SMX displaces warfarin from its albumin binding sites (increasing the free active fraction) and inhibits CYP2C9 (the primary enzyme that metabolizes active S-warfarin), leading to toxic warfarin levels", "TMP-SMX causes acute renal necrosis, preventing the renal excretion of warfarin", "The drug combination causes a primary activation of the plasminogen receptors on the vascular endothelium", "Sulfamethoxazole binds directly to Vitamin K in the gut, completely preventing its bacterial synthesis"]'::jsonb, 1, 'TMP-SMX is a highly protein-bound drug that displaces warfarin from albumin, raising its free active fraction. More importantly, SMX is a potent inhibitor of CYP2C9, the hepatic enzyme that metabolizes the active S-isomer of warfarin. This double mechanism causes rapid, severe warfarin accumulation and bleeding.'),
    (v_case_id, 'Which of the following is the S-isomer of warfarin metabolized by in the liver, which represents the primary target of inhibition by drugs like amiodarone, metronidazole, and TMP-SMX?', '["CYP2C9", "Phase II glucuronosyltransferase", "CYP3A4", "CYP1A2", "CYP2D6"]'::jsonb, 0, 'Active S-warfarin is metabolized primarily by the cytochrome P450 enzyme CYP2C9. Inhibitors of CYP2C9 (amiodarone, metronidazole, TMP-SMX, fluconazole) cause a rapid, dramatic rise in warfarin levels and INR.'),
    (v_case_id, 'Which of the following is the most appropriate initial management step for an asymptomatic patient with an INR of 8.5 without significant bleeding?', '["Administer a 4-factor prothrombin complex concentrate (PCC) bolus immediately", "Administer 4 units of fresh frozen plasma (FFP) and schedule emergency dialysis", "There are no interventions; hold warfarin and discharge the patient home", "Double the dose of warfarin and prescribe daily oral iron supplements", "Hold warfarin, administer oral low-dose Vitamin K (2.5-5 mg), and monitor INR closely"]'::jsonb, 4, 'For patients with INR > 5.0 to 10.0 without active bleeding, guidelines recommend holding warfarin and administering low-dose oral Vitamin K (1 to 2.5 mg) to slowly correct the INR. Intravenous Vitamin K and PCC/FFP are reserved for active, major, life-threatening bleeding.');

