    ---------------------------------------------------------------------------
    -- CASE 46: Codeine Inefficacy and CYP2D6 Polymorphisms (V1)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Codeine Inefficacy and CYP2D6 Polymorphisms (V1)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Codeine Inefficacy and CYP2D6 Polymorphisms (V1)', 'A 80-year-old female undergoes a minor orthopedic procedure and is prescribed oral codeine for post-operative pain control. Despite taking the medication exactly as directed, the patient reports absolutely no pain relief. A genetic analysis reveals the patient is a CYP2D6 ''poor metabolizer.''', 46) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 80-year-old female undergoes a minor orthopedic procedure and is prescribed oral codeine for post-operative pain control. Despite taking the medication exactly as directed, the patient reports absolutely no pain relief. A genetic analysis reveals the patient is a CYP2D6 ''poor metabolizer.''', "order" = 46 WHERE id = v_case_id;
    END IF;

    DELETE FROM case_questions WHERE case_id = v_case_id;
    INSERT INTO case_questions (case_id, question, options, correct_index, explanation) VALUES
    (v_case_id, 'What is the best pharmacological explanation for this patient''s complete lack of pain relief?', '["The patient''s opioid receptors have a primary genetic mutation that prevents all narcotic binding", "The patient''s codeine was rapidly excreted by upregulated renal organic cation transporters", "None of the options; poor metabolizers have no response to any pain medications", "Codeine is a prodrug that must be converted to its active metabolite (morphine) by the hepatic enzyme CYP2C9; poor metabolizers cannot perform this conversion, resulting in therapeutic failure", "Codeine is an active drug that is rapidly inactivated by CYP2D6; poor metabolizers accumulate codeine, which causes a paradoxical pain sensitivity"]'::jsonb, 3, 'Codeine is a prodrug with weak analgesic activity. It must be converted to **morphine** (which has high mu-opioid receptor affinity) by the hepatic enzyme **CYP2D6**. In CYP2D6 ''poor metabolizers'' (about 5-10% of Caucasians), this conversion is absent, leading to a complete lack of pain relief. Conversely, ''ultra-rapid metabolizers'' convert too much codeine, risking morphine toxicity.'),
    (v_case_id, 'Which of the following other common prodrug opioids requires hepatic conversion to its active metabolite by CYP2D6 to provide effective analgesia?', '["Fentanyl", "Tramadol", "Methadone", "Morphine", "Buprenorphine"]'::jsonb, 1, 'Tramadol, like codeine, is a prodrug that must be converted to its active O-desmethyltramadol (M1) metabolite by CYP2D6 to provide meaningful mu-opioid receptor analgesia. Poor metabolizers will also fail to respond to tramadol.'),
    (v_case_id, 'In a patient who is identified as a CYP2D6 ''ultra-rapid metabolizer,'' what represents the primary clinical danger if they are prescribed standard doses of codeine?', '["Complete lack of drug absorption leading to severe therapeutic failure", "Severe hepatorenal syndrome due to drug precipitation in the gallbladder", "Rapid development of a severe allergic rash (Stevens-Johnson syndrome)", "No danger; ultra-rapid metabolizers simply clear the drug faster without side effects", "Life-threatening morphine toxicity (respiratory depression and coma) at standard therapeutic doses"]'::jsonb, 4, 'CYP2D6 ultra-rapid metabolizers convert codeine to morphine exceptionally quickly. This leads to rapid accumulation of morphine, putting the patient at risk of severe opioid toxicity, including respiratory depression and death, even at normal, prescribed doses.');

