    -- CASE 50: Codeine Inefficacy and CYP2D6 Polymorphisms (V5)
    ---------------------------------------------------------------------------
    SELECT id INTO v_case_id FROM case_studies WHERE topic_id = v_topic_id AND title = 'Codeine Inefficacy and CYP2D6 Polymorphisms (V5)' LIMIT 1;
    IF v_case_id IS NULL THEN
        INSERT INTO case_studies (topic_id, title, scenario, "order")
        VALUES (v_topic_id, 'Codeine Inefficacy and CYP2D6 Polymorphisms (V5)', 'A 76-year-old female undergoes a minor orthopedic procedure and is prescribed oral codeine for post-operative pain control. Despite taking the medication exactly as directed, the patient reports absolutely no pain relief. A genetic analysis reveals the patient is a CYP2D6 ''poor metabolizer.''', 50) RETURNING id INTO v_case_id;
    ELSE
        UPDATE case_studies SET scenario = 'A 76-year-old female undergoes a minor orthopedic procedure and is prescribed oral codeine for post-operative pain control. Despite taking the medication exactly as directed, the patient reports absolutely no pain relief. A genetic analysis reveals the patient is a CYP2D6 ''poor metabolizer.''', "order" = 50 WHERE id = v_case_id;
    END IF;

